def transform(grid):
    """Copy the unique non-background colored motif onto matching zero-cell masks."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
    # The marker color is the least frequent nonzero color; the background is more common.
    marker = min(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    r0 = min(r for r, c in pts); c0 = min(c for r, c in pts)
    shape = [(r-r0, c-c0) for r,c in pts]
    sh, sw = max(r for r,c in shape)+1, max(c for r,c in shape)+1
    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == 0 for dr,dc in shape):
                for dr,dc in shape:
                    out[r+dr][c+dc] = marker
    return out
